2bc36959-dcce-4e10-9ecf-2cd418eaa489","displayText":"Wilfrido Vargas","occurrenceId":"ff378d3b-c4df-4bd9-a928-490d1c3fe7e4"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"20610d35-0190-4733-90c0-8c7db5cbe7e0","displayText":"Vickiana","occurrenceId":"a59515a3-c128-40bd-8d74-ba787320d60b"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"f84b208b-dd57-43ad-b2bf-d5099e2f0e0e","displayText":"Olga Lara","occurrenceId":"27fe9407-0b31-47c2-ae46-97bedc5485e9"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2cc97ca9-126d-48c5-922f-e9d5c8b0360d","displayText":"Sonia Silvestre","occurrenceId":"902ccbf5-d064-4deb-b59f-64ade00ae1c7"}},{"text":", Julio Iglesias y Emmanuel.","type":"text"}]},{"type":"paragraph","content":[{"text":"En 1992 Tejada produjo «Bachata Magic», versiones en bachata de baladas cantadas por Ceara y la cantante Audrey Campos, que se convirtió en un éxito inesperado gracias a «Bailar Pegados». Ambos ganaron el premio Aplauso como artista revelación en Miami y Ceara fue nominado a Premios Lo Nuestro. El segundo disco, «Bachata Magic II», incluyó «Lluvia de Besos», tema de la telenovela de Venevisión «Amor de Papel», y «Quedan Palabras». En 1994 presentó el concierto «Lluvia de Besos» en Bellas Artes y mantuvo largas temporadas en el Café Capri de Santo Domingo, donde tenía su propia noche con su banda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Carrera en solitario y composición","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Ceara representó a la República Dominicana en el Festival de Viña del Mar, en Chile, en 1995, y en el Festival OTI en 1996 con «Una Historia Más», escrita por Manuel Jiménez y "},{"type":"artistReference","attrs":{"artistId":"4d3a653c-688e-47c1-8cec-b8cf85a4abac","displayText":"Manuel Tejada","occurrenceId":"377ee063-8e57-4665-b134-c392a193156f"}},{"type":"text","text":". Como compositor escribió «Pídeme» para "},{"type":"artistReference","attrs":{"artistId":"070e7449-814e-4ea6-a009-7a091b7e4878","displayText":"Milly Quezada","occurrenceId":"1fa284c4-62d1-4d33-bc4f-980199db55d0"}},{"type":"text","text":", luego grabada en versión merengue con "},{"type":"artistReference","attrs":{"artistId":"bc310977-31a9-41bb-9af2-7d3a0d7fabdd","displayText":"Fernando Villalona","occurrenceId":"b36cd166-7781-43c9-ad9e-5696826c1835"}},{"type":"text","text":", y «¿Cómo Le Hago Sin Ti?», escrita para un disco de 2005 del actor y músico José Guillermo, que otros grabaron después. Ednita Nazario grabó una canción que él escribió para ella tras pedírsela en 1995. En la década de 2000 interpretó el papel principal en la producción dominicana de «Los Miserables». En 2022 interpretó a Rafael Trujillo en el musical «Mariposas de acero»."}]},{"type":"paragraph","content":[{"text":"Escribió las canciones oficiales de la caminata anual «Caminantes por la Vida», recaudación de fondos para niños con cáncer, entre ellas «Hay Amor en Mi Ciudad» y «Solo Faltas Tú», y «Quiéreme Como Soy», para un proyecto de inclusión de personas con necesidades especiales. Trabaja como vocal coach dirigiendo cantantes en estudios y desde hace más de una década dirige el ciclo anual de conciertos navideños «Navidad entre Amigos» con una orquesta de quince músicos e invitados.","type":"text"}]},{"type":"paragraph","content":[{"text":"«El Saborcito de Tu Amor»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su octava producción, «El Saborcito de Tu Amor», salió el 27 de mayo de 2025 para conmemorar 35 años de carrera. Tiene once canciones que mezclan bachata, balada y merengue, con metáforas de cocina en las letras. Incluye «Así Bonito», que él escribió y ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra","occurrenceId":"dd053062-26a1-4222-bb20-c75becdf15fa"}},{"text":" produjo y arregló en su estudio de Nueva York, y «La Receta Perfecta» con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"79d013c7-dafc-4807-966e-32c370172dee","displayText":"Adalgisa Pantaleón","occurrenceId":"81e14df3-de18-49fd-9b84-e11f14c497d8"}},{"text":". Fue nominado como Compositor y/o Autor de Letras en los Premios Soberano 2026.","type":"text"}]},{"type":"paragraph","content":[{"type":"text","text":"En 2026 presentó «Íntimo» junto a "},{"type":"artistReference","attrs":{"occurrenceId":"f8ec8f5a-dcd3-4350-8a43-4fb6471e0afa","artistId":"79d013c7-dafc-4807-966e-32c370172dee","displayText":"Adalgisa Pantaleón"}},{"type":"text","text":", un espectáculo de canciones y anécdotas en pequeño formato en el bar Juan Lockward del Teatro Nacional. La propuesta continuó con nuevas funciones en Santo Domingo y Santiago, con Emil Pimentel al piano y en la dirección musical, y Eudy David en la percusión."}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"La carrera de Ceara combina un papel público como cantante y compositor romántico con un trabajo menos visible en el estudio de grabación: los coros, los jingles y la dirección vocal que dieron forma al sonido pop dominicano de los años noventa, y canciones como «Lluvia de Besos» y «Pídeme» que siguen en circulación.","type":"text"}]}]},"status_before":"published","status_after":"published","mirror_before":"Francisco José Ceara, conocido artísticamente como Frank Ceara, es un cantante, compositor y vocal coach dominicano nacido en Santo Domingo el 20 de marzo de 1967. Se dio a conocer en 1992 con el proyecto de balada en bachata «Bachata Magic», fue durante años uno de los coristas de estudio más solicitados del país, escribió canciones grabadas por Milly Quezada y otros, y dirige el concierto navideño anual «Navidad entre Amigos». Su álbum de 2025 «El Saborcito de Tu Amor» incluye una canción con Juan Luis Guerra.\n\n**Orígenes**\n\nCeara creció en el barrio Los Prados, de Santo Domingo, en una familia musical; le regalaron un pequeño piano a los seis años y después aprendió a tocar de oído. Su familia esperaba de él una carrera profesional, y a los trece tomó clases de canto y piano a escondidas. Escribió su primera canción, «En Busca de un Amigo», a esa edad para un festival de amigos del colegio, donde quedó entre los primeros lugares. Comenzó medicina, luego administración de empresas y terminó un técnico en hotelería en la Católica antes de elegir la música. Más tarde estudió canto tres años con Marianela Sánchez y un año en Miami.\n\n**Jingles, coros y «Bachata Magic»**\n\nA finales de los años ochenta un amigo del coro estudiantil lo llevó al grupo de rock «Empiphis», donde fue vocalista durante un año hacia 1990 y 1991. Luego trabajó como cantante de jingles y de coros, dentro de un círculo de vocalistas de estudio alrededor del productor Manuel Tejada que incluía a Kiko Rodríguez, y el perfil que él mismo proporcionó al sitio Tambora y Güira le atribuye 222 jingles hacia 1992. A lo largo de los años hizo coros en grabaciones y espectáculos de artistas como Juan Luis Guerra, Wilfrido Vargas, Vickiana, Olga Lara, Sonia Silvestre, Julio Iglesias y Emmanuel.\n\nEn 1992 Tejada produjo «Bachata Magic», versiones en bachata de baladas cantadas por Ceara y la cantante Audrey Campos, que se convirtió en un éxito inesperado gracias a «Bailar Pegados». Ambos ganaron el premio Aplauso como artista revelación en Miami y Ceara fue nominado a Premios Lo Nuestro. El segundo disco, «Bachata Magic II», incluyó «Lluvia de Besos», tema de la telenovela de Venevisión «Amor de Papel», y «Quedan Palabras». En 1994 presentó el concierto «Lluvia de Besos» en Bellas Artes y mantuvo largas temporadas en el Café Capri de Santo Domingo, donde tenía su propia noche con su banda.\n\n**Carrera en solitario y composición**\n\nCeara representó a la República Dominicana en el Festival de Viña del Mar, en Chile, en 1995, y en el Festival OTI en 1996 con «Una Historia Más», escrita por Manuel Jiménez y Manuel Tejada. Como compositor escribió «Pídeme» para Milly Quezada, luego grabada en versión merengue con Fernando Villalona, y «¿Cómo Le Hago Sin Ti?», escrita para un disco de 2005 del actor y músico José Guillermo, que otros grabaron después. Ednita Nazario grabó una canción que él escribió para ella tras pedírsela en 1995. En la década de 2000 interpretó el papel principal en la producción dominicana de «Los Miserables».\n\nEscribió las canciones oficiales de la caminata anual «Caminantes por la Vida», recaudación de fondos para niños con cáncer, entre ellas «Hay Amor en Mi Ciudad» y «Solo Faltas Tú», y «Quiéreme Como Soy», para un proyecto de inclusión de personas con necesidades especiales. Trabaja como vocal coach dirigiendo cantantes en estudios y desde hace más de una década dirige el ciclo anual de conciertos navideños «Navidad entre Amigos» con una orquesta de quince músicos e invitados.\n\n**«El Saborcito de Tu Amor»**\n\nSu octava producción, «El Saborcito de Tu Amor», salió el 27 de mayo de 2025 para conmemorar 35 años de carrera. Tiene once canciones que mezclan bachata, balada y merengue, con metáforas de cocina en las letras. Incluye «Así Bonito», que él escribió y Juan Luis Guerra produjo y arregló en su estudio de Nueva York, y «La Receta Perfecta» con Adalgisa Pantaleón. Fue nominado como Compositor y/o Autor de Letras en los Premios Soberano 2026.\n\n**Legado**\n\nLa carrera de Ceara combina un papel público como cantante y compositor romántico con un trabajo menos visible en el estudio de grabación: los coros, los jingles y la dirección vocal que dieron forma al sonido pop dominicano de los años noventa, y canciones como «Lluvia de Besos» y «Pídeme» que siguen en circulación.","mirror_after":"Francisco José Ceara, conocido artísticamente como Frank Ceara, es un cantante, compositor y vocal coach dominicano nacido en Santo Domingo el 20 de marzo de 1967. Se dio a conocer en 1992 con el proyecto de balada en bachata «Bachata Magic», fue durante años uno de los coristas de estudio más solicitados del país, escribió canciones grabadas por Milly Quezada y otros, y dirige el concierto navideño anual «Navidad entre Amigos». Su álbum de 2025 «El Saborcito de Tu Amor» incluye una canción con Juan Luis Guerra.\n\n**Orígenes**\n\nCeara creció en el barrio Los Prados, de Santo Domingo, en una familia musical; le regalaron un pequeño piano a los seis años y después aprendió a tocar de oído. Su familia esperaba de él una carrera profesional, y a los trece tomó clases de canto y piano a escondidas. Escribió su primera canción, «En Busca de un Amigo», a esa edad para un festival de amigos del colegio, donde quedó entre los primeros lugares. Comenzó medicina, luego administración de empresas y terminó un técnico en hotelería en la Católica antes de elegir la música. Más tarde estudió canto tres años con Marianela Sánchez y un año en Miami.\n\n**Jingles, coros y «Bachata Magic»**\n\nA finales de los años ochenta un amigo del coro estudiantil lo llevó al grupo de rock «Empiphis», donde fue vocalista durante un año hacia 1990 y 1991. Luego trabajó como cantante de jingles y de coros, dentro de un círculo de vocalistas de estudio alrededor del productor Manuel Tejada que incluía a Kiko Rodríguez, y el perfil que él mismo proporcionó al sitio Tambora y Güira le atribuye 222 jingles hacia 1992. A lo largo de los años hizo coros en grabaciones y espectáculos de artistas como Juan Luis Guerra, Wilfrido Vargas, Vickiana, Olga Lara, Sonia Silvestre, Julio Iglesias y Emmanuel.\n\nEn 1992 Tejada produjo «Bachata Magic», versiones en bachata de baladas cantadas por Ceara y la cantante Audrey Campos, que se convirtió en un éxito inesperado gracias a «Bailar Pegados». Ambos ganaron el premio Aplauso como artista revelación en Miami y Ceara fue nominado a Premios Lo Nuestro. El segundo disco, «Bachata Magic II», incluyó «Lluvia de Besos», tema de la telenovela de Venevisión «Amor de Papel», y «Quedan Palabras». En 1994 presentó el concierto «Lluvia de Besos» en Bellas Artes y mantuvo largas temporadas en el Café Capri de Santo Domingo, donde tenía su propia noche con su banda.\n\n**Carrera en solitario y composición**\n\nCeara representó a la República Dominicana en el Festival de Viña del Mar, en Chile, en 1995, y en el Festival OTI en 1996 con «Una Historia Más», escrita por Manuel Jiménez y Manuel Tejada. Como compositor escribió «Pídeme» para Milly Quezada, luego grabada en versión merengue con Fernando Villalona, y «¿Cómo Le Hago Sin Ti?», escrita para un disco de 2005 del actor y músico José Guillermo, que otros grabaron después. Ednita Nazario grabó una canción que él escribió para ella tras pedírsela en 1995. En la década de 2000 interpretó el papel principal en la producción dominicana de «Los Miserables». En 2022 interpretó a Rafael Trujillo en el musical «Mariposas de acero».\n\nEscribió las canciones oficiales de la caminata anual «Caminantes por la Vida», recaudación de fondos para niños con cáncer, entre ellas «Hay Amor en Mi Ciudad» y «Solo Faltas Tú», y «Quiéreme Como Soy», para un proyecto de inclusión de personas con necesidades especiales. Trabaja como vocal coach dirigiendo cantantes en estudios y desde hace más de una década dirige el ciclo anual de conciertos navideños «Navidad entre Amigos» con una orquesta de quince músicos e invitados.\n\n**«El Saborcito de Tu Amor»**\n\nSu octava producción, «El Saborcito de Tu Amor», salió el 27 de mayo de 2025 para conmemorar 35 años de carrera. Tiene once canciones que mezclan bachata, balada y merengue, con metáforas de cocina en las letras. Incluye «Así Bonito», que él escribió y Juan Luis Guerra produjo y arregló en su estudio de Nueva York, y «La Receta Perfecta» con Adalgisa Pantaleón. Fue nominado como Compositor y/o Autor de Letras en los Premios Soberano 2026.\n\nEn 2026 presentó «Íntimo» junto a Adalgisa Pantaleón, un espectáculo de canciones y anécdotas en pequeño formato en el bar Juan Lockward del Teatro Nacional. La propuesta continuó con nuevas funciones en Santo Domingo y Santiago, con Emil Pimentel al piano y en la dirección musical, y Eudy David en la percusión.\n\n**Legado**\n\nLa carrera de Ceara combina un papel público como cantante y compositor romántico con un trabajo menos visible en el estudio de grabación: los coros, los jingles y la dirección vocal que dieron forma al sonido pop dominicano de los años noventa, y canciones como «Lluvia de Besos» y «Pídeme» que siguen en circulación."},{"owner_id":"faaa6c63-d5c5-4667-8d23-b290104cf186","document_id":"1b3b2523-8a57-4308-a105-5fe5f09fc9ae","locale":"en","expected_revision":1,"before":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Héctor Aníbal is the professional name of Héctor Aníbal Estrella Pantaleón, a Dominican singer, actor and photographer born on February 26, 1975, in San Francisco de Macorís, Duarte province. He is the son of singer ","type":"text"},{"type":"artistReference","attrs":{"artistId":"79d013c7-dafc-4807-966e-32c370172dee","displayText":"Adalgisa Pantaleón","occurrenceId":"31dd4b4b-c110-4f15-a452-33640a0e613e"}},{"text":", a member of ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra","occurrenceId":"5fab3d51-b7ae-4db4-89a8-a83fc59adad0"}},{"text":"'s band. His career connects reggae and tropical fusion with romantic songs, musical theater and film.","type":"text"}]},{"type":"paragraph","content":[{"text":"The voice of «Transfusión»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He joined «Transfusión» as lead vocalist in 1993 and became known through the band during the 1990s. In 1995 the group released «Reggae-Ando», a reggae fusion album issued by Sony. Songs associated with that period include «Mujer mujer», «Yo me doy», «El pasito» and «Dulce mujer». The band provided a formative setting for his development as a performer and his relationship with Dominican audiences.","type":"text"}]},{"type":"paragraph","content":[{"text":"«Echa pa ka» and solo recordings","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 2011 he presented «Echa pa ka» with the group «La Cuadra» at Hard Rock Café. Produced by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"34b63c95-f79a-4f7b-aa1d-426926d12959","displayText":"Pavel Núñez","occurrenceId":"8d82a4dc-1b31-4313-abe3-fca1963e966b"}},{"text":" and Alexis de Peña, the record combined bachata, reggae, rock and pop. Its songs included «Yo soy», «Te observo», «Historia de amor», «La necia» and «El Tommy». In 2012 he released «Sigues Siendo» and «Hoy me doy cuenta» and shared «Para cuando hagamos el amor». His solo repertoire developed a romantic approach alongside the energy of his band projects.","type":"text"}]},{"type":"paragraph","content":[{"text":"Theater, film and photography","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He also built an extensive stage career, appearing in musicals including «Jesus Christ Superstar», «Les Misérables», «Cats», «Chicago», «Dreamgirls», «Rent» and «Legally Blonde». Photography is another of his professional activities. In 2018 he received the Premio Soberano for Actor of the Year in the film category for his performance in «El hombre que cuida».","type":"text"}]},{"type":"paragraph","content":[{"text":"The band's return","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 2026 he returned to recording with «Transfusión», which released «Vamo' a fluir» and «Noche de leyenda». The lineup reunited his voice with Rigoberto Zapata on bass and musical direction, Alfio Lora on keyboards and Jean Pimentel on drums. That year he also appeared on «Te amo», the duo «MarteOvenuS»'s version of Franco De Vita's song, combining bolero, pop and bachata.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"His work connects several areas of Dominican performance: reggae fusion bands, solo songs, musical theater characters and cinema. The continuity between voice and acting distinguishes a career that has maintained its connection with music while developing across other artistic disciplines.","type":"text"}]}]},"after":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Héctor Aníbal is the professional name of Héctor Aníbal Estrella Pantaleón, a Dominican singer, actor and photographer born on February 26, 1975, in San Francisco de Macorís, Duarte province. He is the son of singer ","type":"text"},{"type":"artistReference","attrs":{"artistId":"79d013c7-dafc-4807-966e-32c370172dee","displayText":"Adalgisa Pantaleón","occurrenceId":"31dd4b4b-c110-4f15-a452-33640a0e613e"}},{"text":", known for her long association with ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra","occurrenceId":"5fab3d51-b7ae-4db4-89a8-a83fc59adad0"}},{"text":"'s band. His career connects reggae and tropical fusion with romantic songs, musical theater and film.","type":"text"}]},{"type":"paragraph","content":[{"text":"The voice of «Transfusión»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He joined «Transfusión» as lead vocalist in 1993 and became known through the band during the 1990s. In 1995 the group released «Reggae-Ando», a reggae fusion album issued by Sony. Songs associated with that period include «Mujer mujer», «Yo me doy», «El pasito» and «Dulce mujer». The band provided a formative setting for his development as a performer and his relationship with Dominican audiences.","type":"text"}]},{"type":"paragraph","content":[{"text":"«Echa pa ka» and solo recordings","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 2011 he presented «Echa pa ka» with the group «La Cuadra» at Hard Rock Café. Produced by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"34b63c95-f79a-4f7b-aa1d-426926d12959","displayText":"Pavel Núñez","occurrenceId":"8d82a4dc-1b31-4313-abe3-fca1963e966b"}},{"text":" and Alexis de Peña, the record combined bachata, reggae, rock and pop. Its songs included «Yo soy», «Te observo», «Historia de amor», «La necia» and «El Tommy». In 2012 he released «Sigues Siendo» and «Hoy me doy cuenta» and shared «Para cuando hagamos el amor». His solo repertoire developed a romantic approach alongside the energy of his band projects.","type":"text"}]},{"type":"paragraph","content":[{"text":"Theater, film and photography","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"He also built an extensive stage career, appearing in musicals including «Jesus Christ Superstar», «Les Misérables», «Cats», «Chicago», «Dreamgirls», «Rent» and «Legally Blonde». Photography is another of his professional activities. In 2018 he received the Premio Soberano for Actor of the Year in the film category for his performance in «El hombre que cuida».","type":"text"}]},{"type":"paragraph","content":[{"text":"The band's return","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In 2026 he returned to recording with «Transfusión», which released «Vamo' a fluir» and «Noche de leyenda». The lineup reunited his voice with Rigoberto Zapata on bass and musical direction, Alfio Lora on keyboards and Jean Pimentel on drums. That year he also appeared on «Te amo», the duo «MarteOvenuS»'s version of Franco De Vita's song, combining bolero, pop and bachata.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"His work connects several areas of Dominican performance: reggae fusion bands, solo songs, musical theater characters and cinema. The continuity between voice and acting distinguishes a career that has maintained its connection with music while developing across other artistic disciplines.","type":"text"}]}]},"status_before":"published","status_after":"published","mirror_before":null,"mirror_after":"Héctor Aníbal is the professional name of Héctor Aníbal Estrella Pantaleón, a Dominican singer, actor and photographer born on February 26, 1975, in San Francisco de Macorís, Duarte province. He is the son of singer Adalgisa Pantaleón, known for her long association with Juan Luis Guerra's band. His career connects reggae and tropical fusion with romantic songs, musical theater and film.\n\n**The voice of «Transfusión»**\n\nHe joined «Transfusión» as lead vocalist in 1993 and became known through the band during the 1990s. In 1995 the group released «Reggae-Ando», a reggae fusion album issued by Sony. Songs associated with that period include «Mujer mujer», «Yo me doy», «El pasito» and «Dulce mujer». The band provided a formative setting for his development as a performer and his relationship with Dominican audiences.\n\n**«Echa pa ka» and solo recordings**\n\nIn 2011 he presented «Echa pa ka» with the group «La Cuadra» at Hard Rock Café. Produced by Pavel Núñez and Alexis de Peña, the record combined bachata, reggae, rock and pop. Its songs included «Yo soy», «Te observo», «Historia de amor», «La necia» and «El Tommy». In 2012 he released «Sigues Siendo» and «Hoy me doy cuenta» and shared «Para cuando hagamos el amor». His solo repertoire developed a romantic approach alongside the energy of his band projects.\n\n**Theater, film and photography**\n\nHe also built an extensive stage career, appearing in musicals including «Jesus Christ Superstar», «Les Misérables», «Cats», «Chicago», «Dreamgirls», «Rent» and «Legally Blonde». Photography is another of his professional activities. In 2018 he received the Premio Soberano for Actor of the Year in the film category for his performance in «El hombre que cuida».\n\n**The band's return**\n\nIn 2026 he returned to recording with «Transfusión», which released «Vamo' a fluir» and «Noche de leyenda». The lineup reunited his voice with Rigoberto Zapata on bass and musical direction, Alfio Lora on keyboards and Jean Pimentel on drums. That year he also appeared on «Te amo», the duo «MarteOvenuS»'s version of Franco De Vita's song, combining bolero, pop and bachata.\n\n**Legacy**\n\nHis work connects several areas of Dominican performance: reggae fusion bands, solo songs, musical theater characters and cinema. The continuity between voice and acting distinguishes a career that has maintained its connection with music while developing across other artistic disciplines."},{"owner_id":"faaa6c63-d5c5-4667-8d23-b290104cf186","document_id":"0407c48f-e617-4aec-9c2d-7931314d8b3b","locale":"es","expected_revision":1,"before":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Héctor Aníbal, nombre artístico de Héctor Aníbal Estrella Pantaleón, es un cantante, actor y fotógrafo dominicano nacido el 26 de febrero de 1975 en San Francisco de Macorís, provincia Duarte. Es hijo de la cantante ","type":"text"},{"type":"artistReference","attrs":{"artistId":"79d013c7-dafc-4807-966e-32c370172dee","displayText":"Adalgisa Pantaleón","occurrenceId":"cf9ae877-f075-4ac5-9158-60ee6685e152"}},{"text":", integrante de la agrupación de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra","occurrenceId":"7a0ef863-ab3d-4dc3-b6d3-8f52f7391917"}},{"text":". Su trayectoria reúne el reggae y la fusión tropical con la canción romántica, el teatro musical y el cine.","type":"text"}]},{"type":"paragraph","content":[{"text":"La voz de «Transfusión»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 1993 se incorporó como vocalista a «Transfusión», banda con la que se dio a conocer durante los años noventa. En 1995 el grupo publicó «Reggae-Ando», un disco de reggae fusión editado por Sony. De esa etapa proceden canciones como «Mujer mujer», «Yo me doy», «El pasito» y «Dulce mujer». La banda constituyó una plataforma decisiva para su desarrollo como intérprete y para su relación con el público dominicano.","type":"text"}]},{"type":"paragraph","content":[{"text":"«Echa pa ka» y la etapa solista","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 2011 presentó «Echa pa ka» junto al grupo «La Cuadra», en un concierto en Hard Rock Café. La producción estuvo a cargo de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"34b63c95-f79a-4f7b-aa1d-426926d12959","displayText":"Pavel Núñez","occurrenceId":"30773020-a7c3-4d94-bfdc-9a0edd88be34"}},{"text":" y Alexis de Peña y combinó bachata, reggae, rock y pop. Incluyó canciones como «Yo soy», «Te observo», «Historia de amor», «La necia» y «El Tommy». En 2012 publicó «Sigues Siendo» y «Hoy me doy cuenta», y difundió «Para cuando hagamos el amor». Su repertorio solista exploró una vertiente romántica junto a la energía de sus proyectos de banda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Teatro, cine y fotografía","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En paralelo desarrolló una extensa carrera escénica. Su repertorio teatral incluye «Jesucristo Superestrella», «Los miserables», «Cats», «Chicago», «Dreamgirls», «Rent» y «Legalmente rubia». La fotografía constituye otra de sus actividades profesionales. En 2018 recibió el Premio Soberano a Actor del Año, en el renglón de cine, por su actuación en «El hombre que cuida».","type":"text"}]},{"type":"paragraph","content":[{"text":"El regreso de la banda","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 2026 volvió a grabar con «Transfusión», que publicó «Vamo' a fluir» y «Noche de leyenda». La formación reunió nuevamente su voz con Rigoberto Zapata en el bajo y la dirección, Alfio Lora en los teclados y Jean Pimentel en la batería. Ese año también participó en «Te amo», versión de la canción de Franco De Vita realizada por el dúo «MarteOvenuS», que combina bolero, pop y bachata.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su carrera conecta distintos espacios de la interpretación dominicana: la banda de reggae fusión, la canción solista, los personajes del teatro musical y el trabajo cinematográfico. Esa continuidad entre voz y actuación distingue una trayectoria que ha conservado el vínculo con la música mientras se desarrolla en otras disciplinas artísticas.","type":"text"}]}]},"after":{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Héctor Aníbal, nombre artístico de Héctor Aníbal Estrella Pantaleón, es un cantante, actor y fotógrafo dominicano nacido el 26 de febrero de 1975 en San Francisco de Macorís, provincia Duarte. Es hijo de la cantante ","type":"text"},{"type":"artistReference","attrs":{"artistId":"79d013c7-dafc-4807-966e-32c370172dee","displayText":"Adalgisa Pantaleón","occurrenceId":"cf9ae877-f075-4ac5-9158-60ee6685e152"}},{"text":", conocida por su prolongada trayectoria con ","type":"text"},{"type":"artistReference","attrs":{"artistId":"10034596-47cb-46ba-9e80-9ea319a2c0df","displayText":"Juan Luis Guerra","occurrenceId":"7a0ef863-ab3d-4dc3-b6d3-8f52f7391917"}},{"text":". Su trayectoria reúne el reggae y la fusión tropical con la canción romántica, el teatro musical y el cine.","type":"text"}]},{"type":"paragraph","content":[{"text":"La voz de «Transfusión»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 1993 se incorporó como vocalista a «Transfusión», banda con la que se dio a conocer durante los años noventa. En 1995 el grupo publicó «Reggae-Ando», un disco de reggae fusión editado por Sony. De esa etapa proceden canciones como «Mujer mujer», «Yo me doy», «El pasito» y «Dulce mujer». La banda constituyó una plataforma decisiva para su desarrollo como intérprete y para su relación con el público dominicano.","type":"text"}]},{"type":"paragraph","content":[{"text":"«Echa pa ka» y la etapa solista","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 2011 presentó «Echa pa ka» junto al grupo «La Cuadra», en un concierto en Hard Rock Café. La producción estuvo a cargo de ","type":"text"},{"type":"artistReference","attrs":{"artistId":"34b63c95-f79a-4f7b-aa1d-426926d12959","displayText":"Pavel Núñez","occurrenceId":"30773020-a7c3-4d94-bfdc-9a0edd88be34"}},{"text":" y Alexis de Peña y combinó bachata, reggae, rock y pop. Incluyó canciones como «Yo soy», «Te observo», «Historia de amor», «La necia» y «El Tommy». En 2012 publicó «Sigues Siendo» y «Hoy me doy cuenta», y difundió «Para cuando hagamos el amor». Su repertorio solista exploró una vertiente romántica junto a la energía de sus proyectos de banda.","type":"text"}]},{"type":"paragraph","content":[{"text":"Teatro, cine y fotografía","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En paralelo desarrolló una extensa carrera escénica. Su repertorio teatral incluye «Jesucristo Superestrella», «Los miserables», «Cats», «Chicago», «Dreamgirls», «Rent» y «Legalmente rubia». La fotografía constituye otra de sus actividades profesionales. En 2018 recibió el Premio Soberano a Actor del Año, en el renglón de cine, por su actuación en «El hombre que cuida».","type":"text"}]},{"type":"paragraph","content":[{"text":"El regreso de la banda","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"En 2026 volvió a grabar con «Transfusión», que publicó «Vamo' a fluir» y «Noche de leyenda». La formación reunió nuevamente su voz con Rigoberto Zapata en el bajo y la dirección, Alfio Lora en los teclados y Jean Pimentel en la batería. Ese año también participó en «Te amo», versión de la canción de Franco De Vita realizada por el dúo «MarteOvenuS», que combina bolero, pop y bachata.","type":"text"}]},{"type":"paragraph","content":[{"text":"Legado","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Su carrera conecta distintos espacios de la interpretación dominicana: la banda de reggae fusión, la canción solista, los personajes del teatro musical y el trabajo cinematográfico. Esa continuidad entre voz y actuación distingue una trayectoria que ha conservado el vínculo con la música mientras se desarrolla en otras disciplinas artísticas.","type":"text"}]}]},"status_before":"published","status_after":"published","mirror_before":null,"mirror_after":"Héctor Aníbal, nombre artístico de Héctor Aníbal Estrella Pantaleón, es un cantante, actor y fotógrafo dominicano nacido el 26 de febrero de 1975 en San Francisco de Macorís, provincia Duarte. Es hijo de la cantante Adalgisa Pantaleón, conocida por su prolongada trayectoria con Juan Luis Guerra. Su trayectoria reúne el reggae y la fusión tropical con la canción romántica, el teatro musical y el cine.\n\n**La voz de «Transfusión»**\n\nEn 1993 se incorporó como vocalista a «Transfusión», banda con la que se dio a conocer durante los años noventa. En 1995 el grupo publicó «Reggae-Ando», un disco de reggae fusión editado por Sony. De esa etapa proceden canciones como «Mujer mujer», «Yo me doy», «El pasito» y «Dulce mujer». La banda constituyó una plataforma decisiva para su desarrollo como intérprete y para su relación con el público dominicano.\n\n**«Echa pa ka» y la etapa solista**\n\nEn 2011 presentó «Echa pa ka» junto al grupo «La Cuadra», en un concierto en Hard Rock Café. La producción estuvo a cargo de Pavel Núñez y Alexis de Peña y combinó bachata, reggae, rock y pop. Incluyó canciones como «Yo soy», «Te observo», «Historia de amor», «La necia» y «El Tommy». En 2012 publicó «Sigues Siendo» y «Hoy me doy cuenta», y difundió «Para cuando hagamos el amor». Su repertorio solista exploró una vertiente romántica junto a la energía de sus proyectos de banda.\n\n**Teatro, cine y fotografía**\n\nEn paralelo desarrolló una extensa carrera escénica. Su repertorio teatral incluye «Jesucristo Superestrella», «Los miserables», «Cats», «Chicago», «Dreamgirls», «Rent» y «Legalmente rubia». La fotografía constituye otra de sus actividades profesionales. En 2018 recibió el Premio Soberano a Actor del Año, en el renglón de cine, por su actuación en «El hombre que cuida».\n\n**El regreso de la banda**\n\nEn 2026 volvió a grabar con «Transfusión», que publicó «Vamo' a fluir» y «Noche de leyenda». La formación reunió nuevamente su voz con Rigoberto Zapata en el bajo y la dirección, Alfio Lora en los teclados y Jean Pimentel en la batería. Ese año también participó en «Te amo», versión de la canción de Franco De Vita realizada por el dúo «MarteOvenuS», que combina bolero, pop y bachata.\n\n**Legado**\n\nSu carrera conecta distintos espacios de la interpretación dominicana: la banda de reggae fusión, la canción solista, los personajes del teatro musical y el trabajo cinematográfico. Esa continuidad entre voz y actuación distingue una trayectoria que ha conservado el vínculo con la música mientras se desarrolla en otras disciplinas artísticas."}]$approved440$::jsonb;
  item jsonb;
  existing public.editorial_documents%ROWTYPE;
  prior_artists jsonb;
  after_artists jsonb;
  saved record;
BEGIN
  PERFORM 1 FROM public.artists a WHERE a.id IN (SELECT (x->>'owner_id')::uuid FROM jsonb_array_elements(batch) x) ORDER BY a.id FOR UPDATE;
  PERFORM 1 FROM public.editorial_documents d WHERE d.id IN (SELECT (x->>'document_id')::uuid FROM jsonb_array_elements(batch) x) ORDER BY d.id FOR UPDATE;
  SELECT jsonb_object_agg(a.id::text,to_jsonb(a)-'bio_en'-'bio_es'-'updated_at') INTO prior_artists FROM public.artists a WHERE a.id IN (SELECT (x->>'owner_id')::uuid FROM jsonb_array_elements(batch) x);
  FOR item IN SELECT value FROM jsonb_array_elements(batch) LOOP
    SELECT * INTO STRICT existing FROM public.editorial_documents d WHERE d.id=(item->>'document_id')::uuid;
    IF existing.owner_artist_id IS DISTINCT FROM (item->>'owner_id')::uuid OR existing.document_type<>'artist_biography' OR existing.locale<>item->>'locale' OR existing.revision<>(item->>'expected_revision')::integer OR existing.document IS DISTINCT FROM item->'before' OR existing.status<>item->>'status_before' THEN
      RAISE EXCEPTION 'Approved biography precondition changed: % %',item->>'document_id',item->>'locale';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.artists a WHERE a.id=existing.owner_artist_id AND a.status='published' AND (CASE existing.locale WHEN 'en' THEN a.bio_en ELSE a.bio_es END) IS NOT DISTINCT FROM item->>'mirror_before') THEN
      RAISE EXCEPTION 'Artist status/mirror precondition changed: %',existing.owner_artist_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.editorial_document_v1_references(item->'after') n LEFT JOIN public.artists a ON a.id=(n.inline_node->'attrs'->>'artistId')::uuid WHERE a.id IS NULL OR a.status<>'published' OR a.name IS DISTINCT FROM n.inline_node->'attrs'->>'displayText') THEN
      RAISE EXCEPTION 'Reference target precondition changed: %',existing.id;
    END IF;
    SELECT * INTO STRICT saved FROM public.upsert_editorial_document('artist_biography',existing.owner_artist_id,existing.locale,1,item->>'status_after',item->'after',existing.revision);
    IF saved.id<>existing.id OR saved.revision<>existing.revision+1 THEN RAISE EXCEPTION 'Unexpected save result'; END IF;
    UPDATE public.artists SET bio_en=CASE WHEN existing.locale='en' THEN item->>'mirror_after' ELSE bio_en END,bio_es=CASE WHEN existing.locale='es' THEN item->>'mirror_after' ELSE bio_es END WHERE artists.id=existing.owner_artist_id;
    IF NOT EXISTS (SELECT 1 FROM public.editorial_documents d WHERE d.id=existing.id AND d.document=item->'after' AND d.status=item->>'status_after' AND d.revision=existing.revision+1) THEN RAISE EXCEPTION 'Saved document mismatch'; END IF;
    IF (SELECT count(*) FROM public.editorial_entity_references z WHERE z.editorial_document_id=existing.id)<>(SELECT count(*) FROM public.editorial_document_v1_references(item->'after')) OR EXISTS (SELECT 1 FROM public.editorial_document_v1_references(item->'after') n LEFT JOIN public.editorial_entity_references z ON z.editorial_document_id=existing.id AND z.occurrence_id=(n.inline_node->'attrs'->>'occurrenceId')::uuid AND z.target_artist_id=(n.inline_node->'attrs'->>'artistId')::uuid AND z.entity_type='artist' WHERE z.id IS NULL) THEN RAISE EXCEPTION 'Saved reference mismatch'; END IF;
  END LOOP;
  SELECT jsonb_object_agg(a.id::text,to_jsonb(a)-'bio_en'-'bio_es'-'updated_at') INTO after_artists FROM public.artists a WHERE a.id IN (SELECT (x->>'owner_id')::uuid FROM jsonb_array_elements(batch) x);
  IF after_artists IS DISTINCT FROM prior_artists THEN RAISE EXCEPTION 'Unexpected non-biography artist change'; END IF;
END $save440$;
COMMIT;
